-- Generated by ekos-lakehouse (RFC 0195): `copies` in gold__inventory_by_store_rating reconciles to silver.
with mart as (
    select sum("copies") as v from {{ ref('gold__inventory_by_store_rating') }}
),

silver as (
    select count("inventory"."inventory_id") as v
    from {{ ref('public__inventory') }} as "inventory"
    left join {{ ref('public__film') }} as "film"
        on "inventory"."film_id" = "film"."film_id"
)

select mart.v as mart_total, silver.v as silver_total
from mart, silver
where mart.v is distinct from silver.v
